-- Halaman bantuan & tentang untuk pembeli (Profil > Pusat Bantuan / Tentang).
-- Idempoten: isi yang sudah diubah pengurus tidak ditimpa.
INSERT INTO "ContentPage" ("id", "slug", "title", "subtitle", "sections", "footnote", "isPublished", "createdAt", "updatedAt")
VALUES (gen_random_uuid()::text, 'bantuan-pembeli', 'Bantuan Pembeli', 'Cara memesan, membayar, dan mengelola akun di KOMIT.', '[{"heading": "Memesan", "body": "Tambahkan produk ke keranjang, buka tab Pesanan, centang produk yang ingin dipesan, lalu tekan Checkout. Pilih cara menerima: Diantar kurir atau Ambil sendiri di Kopdes/toko. Pesanan memerlukan alamat; atur di Profil > Alamat Pengiriman."}, {"heading": "Cara membayar", "body": "Bayar Online: setelah pesanan dibuat, pilih QRIS, GoPay, ShopeePay, atau Virtual Account, lalu selesaikan sebelum batas waktunya. Status berubah otomatis setelah pembayaran diterima. COD: bayar tunai kepada kurir, hanya untuk pesanan yang diantar. Saldo KOMIT: langsung lunas bila saldo cukup."}, {"heading": "Saldo KOMIT", "body": "Isi ulang di Profil > Saldo KOMIT dengan QRIS, GoPay, atau ShopeePay (minimal Rp10.000). Saldo dipakai membayar pesanan, dan pesanan yang dibatalkan setelah dibayar dengan saldo dikembalikan ke saldo."}, {"heading": "Melacak dan menerima pesanan", "body": "Buka tab Pesanan untuk melihat status. Setelah kurir menandai barang sampai, tekan Konfirmasi Diterima agar pesanan selesai. Setelah selesai, Anda bisa memberi ulasan untuk produknya."}, {"heading": "Membatalkan pesanan", "body": "Pesanan yang belum dibayar dan belum diproses bisa dibatalkan dari detail pesanan. Untuk pesanan yang sudah dibayar, hubungi pengurus Kopdes desa Anda."}, {"heading": "Akun", "body": "Ubah nama dan nomor HP di Profil > Data Pribadi, dan kata sandi di Profil > Privasi & Keamanan. Lupa kata sandi? Hubungi pengurus Kopdes desa Anda."}]'::jsonb, 'Pertanyaan lain? Hubungi pengurus Kopdes desa Anda.', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "ContentPage" ("id", "slug", "title", "subtitle", "sections", "footnote", "isPublished", "createdAt", "updatedAt")
VALUES (gen_random_uuid()::text, 'tentang-komit', 'Tentang KOMIT', 'Koperasi desa digital untuk warga, Kopdes, dan UMKM.', '[{"heading": "Apa itu KOMIT", "body": "KOMIT menghubungkan warga desa dengan Koperasi Desa (Kopdes) dan mitra UMKM di desanya: belanja kebutuhan harian, produk usaha lokal, dan pengantaran oleh kurir Kopdes."}, {"heading": "Kopdes dan mitra UMKM", "body": "Setiap desa memiliki satu Kopdes yang menjual barang kebutuhan sekaligus mengelola marketplace desa. UMKM yang berlokasi di desa yang sama dapat menjadi mitra setelah diverifikasi pengurus Kopdes."}, {"heading": "Pembayaran", "body": "Pembayaran online diproses oleh Midtrans. KOMIT tidak menyimpan data kartu atau rekening pembeli."}]'::jsonb, 'KOMIT — Smart Cooperative Intelligence System.', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
ON CONFLICT ("slug") DO NOTHING;
